import { useState } from "react";

export default function TideCounter() {
  const [hours, setHours] = useState(6);
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", padding: 24 }}>
      <h2 style={{ marginTop: 0 }}>Hours to high water</h2>
      <p style={{ fontSize: 48, margin: "8px 0" }}>{hours}</p>
      <button onClick={() => setHours((h) => Math.max(0, h - 1))}>One hour later</button>{" "}
      <button onClick={() => setHours(6)}>Reset</button>
    </div>
  );
}

# An invented tide table for the harbour trip.
tides = {"high": "12:10", "low": "18:25"}

for name, time in tides.items():
    print(f"{name} water at {time}")
